<?php
/** Full cutover is optional on existing installations; only CLI may install it. */
function legacy_full_ready(mysqli $db): bool {
    return (int)$db->query("SELECT COUNT(*) FROM information_schema.VIEWS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('legacy_full_batches','legacy_full_students','legacy_full_payments','legacy_full_items','legacy_full_journals','legacy_full_coverage')")->fetch_row()[0]===6
        && (int)$db->query("SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_TYPE='BASE TABLE' AND TABLE_NAME IN ('legacy_full_batches_data','legacy_full_students_data','legacy_full_payments_data','legacy_full_items_data','legacy_full_journals_data','legacy_full_coverage_data')")->fetch_row()[0]===6
        && (int)$db->query("SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND (TRIGGER_NAME LIKE 'lful_fixed_%' OR TRIGGER_NAME LIKE 'lful_coverage_%' OR TRIGGER_NAME LIKE 'lful_cutoff_%')")->fetch_row()[0]===17
        && (int)$db->query("SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME LIKE 'lful_gate_%'")->fetch_row()[0]>0;
}
function legacy_full_schema_apply(mysqli $db): void {
    if(PHP_SAPI!=='cli')throw new RuntimeException('Pemasangan hanya melalui CLI.');
    require_once __DIR__.'/legacy_finance_schema.php';legacy_finance_schema_apply($db);
    $defs=[
        'legacy_full_batches'=>"id CHAR(32) PRIMARY KEY,unit_id TINYINT UNSIGNED NOT NULL,source_id BIGINT NOT NULL,version INT UNSIGNED NOT NULL,digest CHAR(64) NOT NULL,cutoff DATETIME NOT NULL,year_id INT NOT NULL,state VARCHAR(24) NOT NULL DEFAULT 'verifying',manifest JSON NOT NULL,before_backup CHAR(32) NOT NULL,after_backup CHAR(32) NULL,actor_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,completed_at TIMESTAMP NULL,UNIQUE KEY(unit_id),UNIQUE KEY(unit_id,id),FOREIGN KEY(unit_id,source_id) REFERENCES legacy_finance_sources_data(unit_id,id),FOREIGN KEY(actor_id) REFERENCES admin(id),CHECK(state IN ('verifying','blocked','completed'))",
        'legacy_full_students'=>"id BIGINT AUTO_INCREMENT PRIMARY KEY,unit_id TINYINT UNSIGNED NOT NULL,batch_id CHAR(32) NOT NULL,source_identity VARCHAR(255) NOT NULL,student_id INT NOT NULL,review_id BIGINT NOT NULL,settings JSON NOT NULL,UNIQUE KEY(unit_id,batch_id,source_identity),UNIQUE KEY(unit_id,student_id),FOREIGN KEY(unit_id,batch_id) REFERENCES legacy_full_batches_data(unit_id,id),FOREIGN KEY(unit_id,student_id) REFERENCES siswa_data(unit_id,id),FOREIGN KEY(unit_id,review_id) REFERENCES legacy_finance_reviews_data(unit_id,id)",
        'legacy_full_payments'=>"id BIGINT AUTO_INCREMENT PRIMARY KEY,unit_id TINYINT UNSIGNED NOT NULL,batch_id CHAR(32) NOT NULL,student_id INT NOT NULL,row_key CHAR(64) NOT NULL,source_table VARCHAR(64) NOT NULL,source_date DATETIME NULL,source_operator VARCHAR(255) NULL,source_period VARCHAR(100) NULL,class_snapshot VARCHAR(100) NOT NULL,total DECIMAL(15,2) NOT NULL,UNIQUE KEY(unit_id,batch_id,row_key),UNIQUE KEY(unit_id,id),KEY(unit_id,student_id,source_date),FOREIGN KEY(unit_id,batch_id) REFERENCES legacy_full_batches_data(unit_id,id),FOREIGN KEY(unit_id,student_id) REFERENCES siswa_data(unit_id,id),CHECK(total>=0)",
        'legacy_full_items'=>"id BIGINT AUTO_INCREMENT PRIMARY KEY,unit_id TINYINT UNSIGNED NOT NULL,payment_id BIGINT NOT NULL,source_column VARCHAR(64) NOT NULL,category VARCHAR(80) NOT NULL,label VARCHAR(150) NOT NULL,amount DECIMAL(15,2) NOT NULL,UNIQUE KEY(unit_id,payment_id,source_column),FOREIGN KEY(unit_id,payment_id) REFERENCES legacy_full_payments_data(unit_id,id),CHECK(amount>=0)",
        'legacy_full_journals'=>"id BIGINT AUTO_INCREMENT PRIMARY KEY,unit_id TINYINT UNSIGNED NOT NULL,batch_id CHAR(32) NOT NULL,student_id INT NOT NULL,row_key CHAR(64) NOT NULL,source_date DATETIME NOT NULL,source_operator VARCHAR(255) NULL,incoming DECIMAL(15,2) NOT NULL,outgoing DECIMAL(15,2) NOT NULL,UNIQUE KEY(unit_id,batch_id,row_key),KEY(unit_id,student_id,source_date),FOREIGN KEY(unit_id,batch_id) REFERENCES legacy_full_batches_data(unit_id,id),FOREIGN KEY(unit_id,student_id) REFERENCES siswa_data(unit_id,id),CHECK((incoming>0 AND outgoing=0) OR (incoming=0 AND outgoing>0))",
        'legacy_full_coverage'=>"id BIGINT AUTO_INCREMENT PRIMARY KEY,unit_id TINYINT UNSIGNED NOT NULL,batch_id CHAR(32) NOT NULL,student_id INT NOT NULL,category VARCHAR(80) NOT NULL,period VARCHAR(20) NOT NULL,disposition VARCHAR(24) NOT NULL,evidence VARCHAR(1000) NOT NULL,UNIQUE KEY(unit_id,student_id,category,period),FOREIGN KEY(unit_id,batch_id) REFERENCES legacy_full_batches_data(unit_id,id),FOREIGN KEY(unit_id,student_id) REFERENCES siswa_data(unit_id,id),CHECK(disposition IN ('settled','legacy_debt','not_applicable'))"
    ];
    foreach($defs as $name=>$ddl){$db->query("CREATE TABLE IF NOT EXISTS {$name}_data ($ddl) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci");$db->query("CREATE OR REPLACE VIEW $name AS SELECT * FROM {$name}_data WHERE current_unit_id()=0 OR unit_id=current_unit_id() WITH CASCADED CHECK OPTION");}
    // Ordinary writes must not race cutover, or continue after failed verification.
    $tables=$db->query("SELECT TABLE_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND COLUMN_NAME='unit_id' AND TABLE_NAME LIKE '%\\_data' AND TABLE_NAME NOT LIKE 'legacy_full_%' AND TABLE_NAME NOT LIKE 'legacy_finance_%'")->fetch_all(MYSQLI_ASSOC);
    foreach($tables as $row){$table=$row['TABLE_NAME'];if(!preg_match('/^[a-zA-Z0-9_]+$/D',$table))throw new RuntimeException('Invalid schema table');
        foreach(['INSERT'=>'NEW','UPDATE'=>'NEW','DELETE'=>'OLD'] as $event=>$side){$name='lful_gate_'.substr(hash('sha256',$table.$event),0,18);
            if(!(int)$db->query("SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME='$name'")->fetch_row()[0])$db->query("CREATE TRIGGER $name BEFORE $event ON `$table` FOR EACH ROW BEGIN IF COALESCE(@legacy_full_apply,0)<>1 AND EXISTS(SELECT 1 FROM legacy_full_batches_data WHERE unit_id=$side.unit_id AND state<>'completed') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unit menunggu verifikasi migrasi penuh'; END IF; END");
        }
    }
    // Immutable projections are never edited by normal payment endpoints.
    foreach(['legacy_full_students','legacy_full_payments','legacy_full_items','legacy_full_journals','legacy_full_coverage'] as $table)foreach(['UPDATE','DELETE'] as $event){$name='lful_fixed_'.substr(hash('sha256',$table.$event),0,18);if(!(int)$db->query("SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME='$name'")->fetch_row()[0])$db->query("CREATE TRIGGER $name BEFORE $event ON {$table}_data FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Histori migrasi tidak dapat diubah langsung'");}
    foreach(['tagihan_spp_data'=>'spp','tagihan_komite_data'=>'komite','tagihan_daftar_ulang_data'=>'daftar_ulang','tagihan_biaya_lain_data'=>'other'] as $table=>$category){
        $period=match($category){'spp','komite'=>"CONCAT(NEW.tahun,'-',LPAD(NEW.bulan,2,'0'))",'daftar_ulang'=>'NEW.tahun_ajaran_snapshot',default=>"DATE_FORMAT(COALESCE(NEW.created_at,NOW()),'%Y-%m')"};
        $cat=$category==='other'?"CONCAT('biaya_lain:',NEW.master_biaya_lain_id)":"'$category'";
        $prior=in_array($category,['spp','komite'],true)?" OR $period<JSON_UNQUOTE(JSON_EXTRACT(fs.settings,'$.start_period'))":'';
        $coveragePeriod=$category==='other'?'TRUE':"c.period=$period";
        $name='lful_coverage_'.substr(hash('sha256',$table),0,16);
        $db->query("DROP TRIGGER IF EXISTS $name");
        $db->query("CREATE TRIGGER $name BEFORE INSERT ON $table FOR EACH ROW BEGIN IF COALESCE(@legacy_full_apply,0)<>1 AND EXISTS(SELECT 1 FROM legacy_full_students_data fs JOIN siswa_data s ON s.id=fs.student_id AND s.unit_id=fs.unit_id WHERE fs.unit_id=NEW.unit_id AND s.NO_INDUK=NEW.no_induk AND (EXISTS(SELECT 1 FROM legacy_full_coverage_data c WHERE c.unit_id=fs.unit_id AND c.student_id=fs.student_id AND c.category=$cat AND $coveragePeriod)$prior)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Periode sudah tercakup migrasi Legacy'; END IF; END");
    }
    foreach(['bayar_data'=>'TGL_BYR','transaksi_m_data'=>'TANGGAL','transaksi_k_data'=>'TANGGAL'] as $table=>$column){$name='lful_cutoff_'.substr(hash('sha256',$table),0,18);if(!(int)$db->query("SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME='$name'")->fetch_row()[0])$db->query("CREATE TRIGGER $name BEFORE INSERT ON $table FOR EACH ROW BEGIN IF COALESCE(@legacy_full_apply,0)<>1 AND EXISTS(SELECT 1 FROM legacy_full_batches_data WHERE unit_id=NEW.unit_id AND NEW.`$column`<cutoff) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Tanggal transaksi mendahului peralihan Legacy'; END IF; END");}
}
